import {markdownWorkflowCoordinator} from '../../docusaurus-utils/src/markdownLinks';
import {normalizeAdmonitionOptions} from './remark/admonitions';
import type {Options} from './loader';

export {markdownWorkflowCoordinator};

/**
 * Preprocess the string before passing it to MDX
 * This is not particularly recommended but makes it easier to upgrade to MDX 2
 */
export default function preprocessContent({
  fileContent: initialFileContent,
  filePath,
  markdownConfig,
  admonitions,
}: {
  fileContent: string;
  filePath: string;
  markdownConfig: Options['markdownConfig'];
  admonitions: Options['admonitions'] | undefined;
}): string {
  const keywords = admonitions
    ? normalizeAdmonitionOptions(admonitions).keywords
    : undefined;
  return markdownWorkflowCoordinator.preprocessMdxContent({
    initialFileContent,
    filePath,
    markdownConfig,
    headingIdsEnabled: Boolean(markdownConfig.mdx1Compat.headingIds),
    admonitionsEnabled: Boolean(
      markdownConfig.mdx1Compat.admonitions && admonitions,
    ),
    admonitionKeywords: keywords,
  });
}
